'use strict';
const $=id=>document.getElementById(id), n=(tag,text='',cls='')=>{let el=document.createElement(tag);el.textContent=text;if(cls)el.className=cls;return el};
const dt=new Intl.DateTimeFormat('ru-RU',{dateStyle:'short',timeStyle:'medium',timeZone:'Europe/Moscow'}), nf=new Intl.NumberFormat('ru-RU');
let dialogFilter='all';
const dialogGroup=d=>['error','uncertain'].includes(d.agentStatus?.status)?'attention':d.messages.at(-1)?.role==='user'?(d.messages.some(m=>m.role==='assistant')?'waiting':'new'):'answered';
let agentStatus={}, state={events:[],sync:{}},dialogs=[],accounts={adilya:{name:'Адиля'},lyubov:{name:'Любовь'},mexico:{name:'Мексика'}},period=0,selected=null,view='dialogs',busy=false;
const dialogKey=d=>d.account+':'+d.contact;
