async function api(path){let r=await fetch(path,{cache:'no-store'});if(!r.ok)throw Error('Не удалось загрузить данные ('+r.status+')');return r.json()}
function filtered(){return state.events.filter(e=>($('accountFilter').value==='all'||e.account===$('accountFilter').value)&&(!period||new Date(e.at)>=new Date(new Date().toLocaleDateString('en-CA',{timeZone:'Europe/Moscow'})+'T00:00:00+03:00').getTime()-(period-1)*86400000))}
function showView(v){view=v;document.querySelectorAll('.view').forEach(x=>x.hidden=x.id!=='view-'+v);document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.view===v));let names={overview:'Обзор агента',dialogs:'Переписки',analytics:'Воронка и динамика',activity:'Журнал работы',settings:'Подключения'};$('pageTitle').textContent=names[v];$('breadcrumbPage').textContent=names[v];$('pageSubtitle').textContent=v==='dialogs'?'Вся сохранённая переписка: что написали мы и что ответил собеседник.':'Данные агента и состояние подключений.';history.replaceState(null,'','#'+v)}
function card(label,value,foot){let a=n('article','','kpi');a.append(n('div',label,'kpi-head'),n('div',num(value),'kpi-value'),n('div',foot,'kpi-foot'));return a}
function renderMessages(target,doc){let box=$(target);const signature=JSON.stringify([dialogKey(doc),doc.messages,accounts[doc.account]?.name]);if(box.dataset.signature===signature)return;let nearBottom=box.scrollHeight-box.scrollTop-box.clientHeight<80;let previous=box.dataset.contact;box.dataset.signature=signature;box.dataset.contact=dialogKey(doc);box.replaceChildren();if(!doc.messages.length)box.append(n('p','История этого диалога ещё не считана с сайта.','empty'));for(let m of doc.messages){let b=n('div','','bubble '+(m.role==='user'?'incoming':'outgoing'));b.append(n('small',m.role==='user'?doc.name:(accounts[doc.account]?.name||'Анкета')+(m.authorKind==='agent'?' · автобот':m.authorKind==='session'?' · сессионный тест':' · исходящее')),n('div',m.text),n('time',m.date||''));box.append(b)}if(nearBottom||previous!==dialogKey(doc))box.scrollTop=box.scrollHeight}
function selectDialog(key){selected=key;let doc=dialogs.find(d=>dialogKey(d)===key);if(!doc)return;$('chatTitle').textContent=doc.name;$('chatMeta').textContent=(accounts[doc.account]?.name||doc.account)+' · '+doc.messages.length+' сообщений · '+(doc.autonomousSent||0)+' ответов автобота · '+(doc.sessionSent||0)+' сессионных';$('chatProfile').hidden=false;$('chatProfile').href='https://loveplanet.ru/page/'+encodeURIComponent(doc.contact);$('chatStatus').textContent='Считано с сайта: '+stamp(doc.updatedAt)+' · Панель проверяет локальную историю каждые 5 секунд';renderMessages('chatMessages',doc);document.querySelectorAll('.contact-item').forEach(x=>x.classList.toggle('selected',x.dataset.contact===key))}
function render(){let es=filtered(),ids=new Set(es.map(e=>e.account+':'+e.contact)),synced=new Set(state.sync.syncedEventIds||[]),inv=new Set(es.filter(e=>e.telegramInvitation===true).map(e=>e.account+':'+e.contact));$('profileStrip').replaceChildren(...Object.entries(accounts).map(([id,a])=>{let b=n('button','','profile-chip');b.classList.toggle('selected',$('accountFilter').value===id);let connected=agentStatus.accounts?.[id]?.status==='connected';b.append(n('span',a.name[0],'avatar'),n('strong',a.name),n('small',connected?'Расширение на связи · '+(agentStatus.accounts[id].scan?.version||'версия неизвестна'):'Нет связи с браузером'),n('span',dialogs.filter(d=>d.account===id).length+' сохранено · '+(agentStatus.accounts[id]?.scan?.loaded??'?')+' в списке','tag'));b.onclick=()=>{$('accountFilter').value=$('accountFilter').value===id?'all':id;render()};return b}));$('navCount').textContent=dialogs.length;$('conversationCount').textContent=dialogs.length;
$('kpis').replaceChildren(card('Обработано диалогов',ids.size,'С подтверждёнными ответами'),card('Ответов автобота',es.filter(e=>e.autonomous).length,'Сессионных ответов: '+es.filter(e=>!e.autonomous).length),card('Приглашены в Telegram',inv.size,'Вход в Telegram не подтверждён'),card('Сессионных ответов',es.filter(e=>!e.autonomous).length,'Отдельно от автобота'));
const uncertain=(agentStatus.counts||[]).filter(x=>x.status==='uncertain').reduce((n,x)=>n+x.count,0);$('syncTitle').textContent=uncertain?'Доставка требует проверки: '+uncertain:'Только LovePlanet · локальная статистика';$('syncMessage').textContent=uncertain?'Сайт ещё не подтвердил эти отправки. Они не считаются доставленными и не повторяются вслепую. Связь с расширением не означает, что сайт доступен.':'Автоответы и сессионные отправки учитываются отдельно. Запись в Google Sheets отключена.';
const query=$('search').value.toLowerCase();let shown=dialogs.filter(d=>($('accountFilter').value==='all'||d.account===$('accountFilter').value)&&(!period||new Date(d.updatedAt)>=Date.now()-period*86400000)&&(!query||[d.name,d.contact,...d.messages.map(m=>m.text)].join(' ').toLowerCase().includes(query))).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));
const groups=[['all','Все'],['new','Новые'],['waiting','Ждут ответа'],['answered','Отвеченные'],['attention','Ошибки']];
$('dialogTabs').replaceChildren(...groups.map(([id,label])=>{let b=n('button',label+' '+shown.filter(d=>id==='all'||dialogGroup(d)===id).length);b.classList.toggle('selected',dialogFilter===id);b.onclick=()=>{dialogFilter=id;render()};return b}));
shown=shown.filter(d=>dialogFilter==='all'||dialogGroup(d)===dialogFilter);$('conversationCount').textContent=shown.length;
function contactButton(d){let b=n('button','','contact-item');b.type='button';b.dataset.contact=dialogKey(d);b.append(n('span',d.name[0],'avatar'));let t=n('div','','contact-text'),last=d.messages.at(-1);t.append(n('strong',d.name),n('p',last?(last.role==='user'?'': 'Вы: ')+last.text:'История ещё не считана'),n('small',(accounts[d.account]?.name||d.account)+' · '+({queued:'Ожидает времени ответа',generating:'Модель готовит ответ',ready:'В очереди отправки',sending:'Проверка отправки',sent:'Ответ отправлен',uncertain:'Доставка не подтверждена',error:'Ошибка генерации',superseded:'Ожидает нового сообщения',session_test:'Сессионный тест'}[d.agentStatus?.status]||'История считана')+(d.agentStatus?.error?' · '+d.agentStatus.error:'')));b.append(t);b.onclick=()=>{showView('dialogs');selectDialog(dialogKey(d))};return b}
$('allDialogs').replaceChildren(...(shown.length?shown.map(contactButton):[n('p','Нет диалогов по выбранным фильтрам','empty')]));$('recentDialogs').replaceChildren(...shown.slice(0,5).map(contactButton));if(shown.length&&!shown.some(d=>dialogKey(d)===selected))selected=dialogKey(shown[0]);if(shown.length)selectDialog(selected);else{$('chatTitle').textContent='Нет диалогов';$('chatMessages').replaceChildren();$('chatMeta').textContent='Измени фильтр или поисковый запрос';$('chatProfile').hidden=true}
$('eventLog').replaceChildren(...es.slice().reverse().map(e=>{let row=n('div','','event-row'),body=n('div');body.append(n('strong',e.name+(e.autonomous?' · автобот · доставка подтверждена':' · сессионный тест · доставка подтверждена')),n('p',e.reply));row.append(n('span','','event-dot'),body,n('time',stamp(e.at)));return row}));
$('accountCards').replaceChildren(...Object.entries(accounts).map(([id,a])=>{let row=n('div','','account-row');row.append(n('span',a.name[0],'avatar'),n('strong',a.name),n('span',es.filter(e=>e.account===id).length+' ответов','tag'));return row}));
$('attention').replaceChildren(...['Автономная доставка: смотри статус подключения браузера.','Статистика: только локальные события LovePlanet', 'Арсений: сообщение скрыто за платным доступом; пропущено.'].map(t=>n('div',t,'attention-item')));
$('liveFunnel').replaceChildren(...[['Диалоги',ids.size],['Приглашения',inv.size],['Подтверждённые входы',null]].map(([label,value])=>{let row=n('div','','funnel-row');row.append(n('div',label+' · '+num(value),'funnel-label'));return row}));
let buckets={};for(let e of es){let h=new Intl.DateTimeFormat('ru-RU',{hour:'2-digit',timeZone:'Europe/Moscow'}).format(new Date(e.at))+':00';buckets[h]=(buckets[h]||0)+1}let peak=Math.max(1,...Object.values(buckets));$('activityChart').replaceChildren(...Object.entries(buckets).map(([h,c])=>{let col=n('div','','chart-column'),bar=n('div','','chart-bar');bar.style.height=(c/peak*100)+'px';col.append(n('span',String(c),'chart-value'),bar,n('span',h,'chart-time'));return col}));$('chartTotal').textContent=es.length+' ответов';}
async function metrics(){try{let m=await api('/api/metrics?days='+period);$('sheetSource').textContent='Локальный журнал · '+stamp(m.fetchedAt);$('attribution').textContent='Только подтверждённые события LovePlanet. Данных других площадок нет.';$('sheetKpis').replaceChildren(...[['dialogues','Диалоги LovePlanet'],['invited','Приглашения LovePlanet'],['autonomous','Ответы автобота'],['session','Сессионные ответы']].map(([k,l])=>card(l,m.totals[k],'Из журнала LovePlanet')));$('days').replaceChildren(...m.days.slice().reverse().filter(d=>Object.entries(d).some(([k,v])=>k!=='day'&&v!=null)).map(d=>{let tr=n('tr');tr.append(n('td',d.day),...['dialogues','invited','autonomous','session','sent'].map(k=>n('td',num(d[k]))));return tr}))}catch(e){$('sheetSource').textContent=e.message}}
async function refresh(){if(busy)return;busy=true;try{let [live,ds]=await Promise.all([api('/api/live-session'),api('/api/dialogs')]);state=live;dialogs=ds;render();$('freshness').textContent='Обновлено '+new Date().toLocaleTimeString('ru-RU');}catch(e){$('freshness').textContent=e.message;$('syncTitle').textContent='Нет связи с локальным сервером';$('syncMessage').textContent=e.message}finally{busy=false}}
async function status(){try{let s=await api('/api/status');accounts=s.accounts;agentStatus=s.liveAgent||{};$('agentConnection').textContent='Аккаунтов подключено: '+Object.values(agentStatus.accounts||{}).filter(a=>a.status==='connected').length+' / 3';$('sidebarModel').textContent=s.model;$('sidebarProvider').textContent=s.provider==='openrouter'?'OpenRouter':'Ollama';$('connections').replaceChildren(...[[s.provider==='openrouter'?'OpenRouter':'Ollama',s.model+' · '+s.ollama],['Браузерный агент',s.liveAgent?.status||'Не подключён'],['Размещение',s.deployment==='server'?'Сервер':'Локально на Mac'],['Статистика','Локально · только LovePlanet']].map(([k,v])=>{let row=n('div','','connection');row.append(n('strong',k),n('span',v,'tag'));return row}));render()}catch(e){$('connections').textContent=e.message}}
$('toBottom').onclick=()=>{$('chatMessages').scrollTop=$('chatMessages').scrollHeight};
$('refresh').onclick=()=>{refresh();status();metrics()};$('accountFilter').onchange=render;$('search').oninput=render;document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>showView(b.dataset.view));document.querySelectorAll('[data-days]').forEach(b=>b.onclick=()=>{period=Number(b.dataset.days);document.querySelectorAll('[data-days]').forEach(x=>x.classList.toggle('selected',x===b));render();metrics()});
$('export').onclick=()=>{let cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';let rows=[['Дата','Анкета','Диалог','Сообщение'],...filtered().map(e=>[stamp(e.at),accounts[e.account]?.name||e.account,e.name,e.reply])];let url=URL.createObjectURL(new Blob(['\ufeff'+rows.map(r=>r.map(cell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'})),a=n('a');a.href=url;a.download='loveplanet-events.csv';a.click();URL.revokeObjectURL(url)};
$('closeDetails').onclick=()=>$('details').close();showView(['overview','dialogs','analytics','activity','settings'].includes(location.hash.slice(1))?location.hash.slice(1):'dialogs');refresh();status();metrics();setInterval(refresh,5000);setInterval(status,5000);setInterval(()=>$('clock').textContent=new Date().toLocaleTimeString('ru-RU',{timeZone:'Europe/Moscow'}),1000);
